  Print["  sum w  = ", Total[ws], "  sum k = ", Total[ks]];

  elapsed = AbsoluteTiming[amp = BGAmplitude[ks, ws, gVal]][[1]];

  Print["  A_", n, " = ", Simplify[amp]];
